    73	        // Animals get no Pawn_AbilityTracker (RaceProperties.ShouldHaveAbilityTracker); the hediff's <abilities> need one.
    74	        private void EnsureAbilityTracker()
    75	        {
    76	            Pawn p = Pawn;
