    81	        public override void PostPostApplyDamage(DamageInfo dinfo, float totalDamageDealt)
    82	        {
    83	            base.PostPostApplyDamage(dinfo, totalDamageDealt);
    84	            Pawn p = Pawn;
    85	            if (p == null || !p.Spawned)
    86	                return;
    87	            RM_SwellKernel.SwellSource src = SourceOf(dinfo);
    88	            lastSource = src.ToString();
    89	            if (!RM_SwellKernel.CanSwell(state, On, p.Dead, totalDamageDealt, Now))
    90	                return;
    91	            if (!RM_SwellKernel.SourceProvokes(src, RM_TheForgeSettings.dhoggurSwellEnvironmentTriggers))
    92	                return;
    93	            BeginSwell(dinfo.Instigator);
    94	        }
