    96	        // Who hurt it. A pawn's attack reaches here with the pawn as instigator (melee, a shot, a thrown grenade); a
    97	        // turret's shell or a trap's spike names the building. Weather scald, the melt-back's burn and other hazards
    98	        // build their DamageInfo with no instigator; a Fire, a gas cloud or a vortex names itself (not a pawn or a
    99	        // weapon), so all of those are the environment.
   100	        public static RM_SwellKernel.SwellSource SourceOf(DamageInfo dinfo)
   101	        {
   102	            Thing inst = dinfo.Instigator;
   103	            if (inst is Pawn)
   104	                return RM_SwellKernel.SwellSource.Pawn;
   105	            if (inst is Building_Turret || inst is Building_Trap)
   106	                return RM_SwellKernel.SwellSource.WeaponBuilding;
   107	            return RM_SwellKernel.SwellSource.Environment;
   108	        }
