   110	        public void BeginSwell(Thing instigator)
   111	        {
   112	            Pawn p = Pawn;
   113	            EnsureAbilityTracker();
   114	            RM_SwellKernel.Begin(ref state, Now, RM_SwellKernel.DurationTicks(RM_TheForgeSettings.dhoggurSwellHours));
   115	            RM_DhoggurSwellRegistry.Set(p, true);
   116	            if (!p.health.hediffSet.HasHediff(Props.swellHediff))
   117	                p.health.AddHediff(Props.swellHediff);
   118	            p.abilities?.Notify_TemporaryAbilitiesChanged();
   119	            Enrage(p, instigator);
   120	            Burst(p, 4f);
   121	            p.Drawer?.renderer?.SetAllGraphicsDirty();
   122	            if (p.Map == Find.CurrentMap && p.Faction == null)
   123	                Messages.Message("The dhoggur swells with a violent chemical reaction!", p, MessageTypeDefOf.ThreatSmall, false);
   124	        }
