   126	        // Shrinking divides HealthScale by the scale again, so wounds taken while swollen can kill it as it shrinks. Owner
   127	        // card 2026-10-16: "Keep it, it is the price of the swell." Do not add a guard.
   128	        public void EndSwell()
   129	        {
   130	            Pawn p = Pawn;
   131	            RM_SwellKernel.End(ref state, Now, RM_SwellKernel.CooldownTicks(RM_TheForgeSettings.dhoggurCooldownDays));
   132	            RM_DhoggurSwellRegistry.Set(p, false);
   133	            Hediff h = p.health.hediffSet.GetFirstHediffOfDef(Props.swellHediff);
   134	            if (h != null)
   135	                p.health.RemoveHediff(h);
