   262	    // The condition itself. Its one stage's MeleeDamageFactor is rebuilt from the scale setting (so tuning it works),
   263	    // keeping every other field of the XML stage.
   264	    public class RM_Hediff_DhoggurSwell : HediffWithComps
   265	    {
   266	        private static HediffStage cached;
   267	        private static float cachedScale = -1f;
   268	        private static HediffDef cachedFor;
   269	
   270	        public override HediffStage CurStage
   271	        {
   272	            get
   273	            {
   274	                HediffStage xml = base.CurStage;
   275	                if (xml == null)
   276	                    return null;
   277	                float s = RM_SwellKernel.Scale(true, RM_TheForgeSettings.dhoggurSwellScale);
   278	                if (cached == null || cachedScale != s || cachedFor != def)
   279	                {
   280	                    HediffStage st = new HediffStage();
   281	                    foreach (var f in typeof(HediffStage).GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
   282	                        f.SetValue(st, f.GetValue(xml));
   283	                    st.statFactors = new List<StatModifier>();
   284	                    if (xml.statFactors != null)
   285	                        foreach (StatModifier m in xml.statFactors)
   286	                            if (m.stat != StatDefOf.MeleeDamageFactor) st.statFactors.Add(m);
   287	                    st.statFactors.Add(new StatModifier { stat = StatDefOf.MeleeDamageFactor, value = s });
   288	                    cached = st;
   289	                    cachedScale = s;
   290	                    cachedFor = def;
   291	                }
   292	                return cached;
   293	            }
   294	        }
   295	    }
